/* Search operates over all entries before slicing a 15-item page. */
const KANJI_PAGE_SIZE=15;
const KANA_ROMAJI={};
for(const group of Object.values(KANA_GROUPS))for(const cell of group.rows.flat().filter(Boolean))KANA_ROMAJI[cell[0]]=cell[1];
// Foreign-sound kana appear in vocabulary examples but not the basic kana grid.
Object.assign(KANA_ROMAJI,{'うぃ':'wi','うぇ':'we','うぉ':'wo','いぇ':'ye','しぇ':'she','じぇ':'je','ちぇ':'che','てぃ':'ti','てゅ':'tyu','でぃ':'di','でゅ':'dyu','とぅ':'tu','どぅ':'du','ふぁ':'fa','ふぃ':'fi','ふぇ':'fe','ふぉ':'fo','ふゅ':'fyu','つぁ':'tsa','つぃ':'tsi','つぇ':'tse','つぉ':'tso','ゔ':'vu','ゔぁ':'va','ゔぃ':'vi','ゔぇ':'ve','ゔぉ':'vo','ゔゅ':'vyu','ぢゃ':'ja','ぢゅ':'ju','ぢょ':'jo','ゐ':'i','ゑ':'e'});
function kanjiToHiragana(text){return [...text].map(c=>{const n=c.charCodeAt(0);return n>=0x30a1&&n<=0x30f6?String.fromCharCode(n-96):c}).join('')}
function kanjiRomanize(text){const s=kanjiToHiragana(String(text).normalize('NFKC')).replace(/[.()（）・]/g,'');let out='';for(let i=0;i<s.length;i++){let c=s[i];if(c==='っ'){const next=KANA_ROMAJI[s.slice(i+1,i+3)]||KANA_ROMAJI[s[i+1]]||'';out+=next[0]&&/[bcdfghjklmnpqrstvwxyz]/.test(next[0])?next[0]:'';continue}if(c==='ー'){out+=(out.match(/[aeiou](?=[^aeiou]*$)/)||[''])[0];continue}const pair=s.slice(i,i+2);if(KANA_ROMAJI[pair]){out+=KANA_ROMAJI[pair];i++}else out+=KANA_ROMAJI[c]||c}return out}
function kanjiNormalize(text){let s=kanjiRomanize(String(text).trim().toLowerCase()).replace(/[āēīōū]/g,c=>({ā:'aa',ē:'ee',ī:'ii',ō:'oo',ū:'uu'}[c]));s=s.replace(/shi/g,'si').replace(/chi/g,'ti').replace(/tsu/g,'tu').replace(/fu/g,'hu').replace(/sha/g,'sya').replace(/shu/g,'syu').replace(/sho/g,'syo').replace(/cha/g,'tya').replace(/chu/g,'tyu').replace(/cho/g,'tyo').replace(/ji/g,'zi').replace(/jya|ja/g,'zya').replace(/jyu|ju/g,'zyu').replace(/jyo|jo/g,'zyo');return s.replace(/ou|oo/g,'o').replace(/aa/g,'a').replace(/ii/g,'i').replace(/uu/g,'u').replace(/ee/g,'e').replace(/[\s'’.,;:!?()（）\-–—・]/g,'')}
const KANJI_SEARCH_INDEX=[...KANJI_DATA,...KANJI_N4_DATA].map(k=>{const raw=[k.char,k.meaning,k.english,...k.on,...k.kun,...k.examples.flatMap(e=>[e.word,e.kana,e.meaning])];const fields=raw.map(kanjiNormalize).flatMap(s=>[s,s.replace(/([bcdfghjklmnpqrstvwxyz])\1/g,'$1')]);return {entry:k,fields:[...new Set(fields)]}});
function findKanji(query='',category='all',source='all',level=(typeof prefs!=='undefined'?prefs.level:'N5'),scope='all'){const q=kanjiNormalize(query);return KANJI_SEARCH_INDEX.filter(({entry:k})=>(k.level||'N5')===level&&(category==='all'||k.category===category)&&(source==='all'||k.source.id===source)&&(scope==='all'||k.scope===scope)).map(({entry,fields})=>{let rank=9;if(!q)rank=0;else if(entry.char===String(query).trim().normalize('NFKC'))rank=0;else if(fields.some(f=>f===q))rank=1;else if(fields.some(f=>f.startsWith(q)))rank=2;else if(fields.some(f=>f.includes(q)))rank=3;return {entry,rank}}).filter(x=>x.rank<9).sort((a,b)=>a.rank-b.rank||a.entry.order-b.entry.order).map(x=>x.entry)}
function kanjiPageSlice(results,page=1){const totalPages=Math.max(1,Math.ceil(results.length/KANJI_PAGE_SIZE)),current=Math.min(totalPages,Math.max(1,Math.floor(Number(page)||1)));return {items:results.slice((current-1)*KANJI_PAGE_SIZE,current*KANJI_PAGE_SIZE),page:current,totalPages,total:results.length}}
